      'Content-Disposition: form-data; name="persona"',
      '',
      'Maria, Ukrainian refugee, Munich.',
      `--${boundary}`,
      'Content-Disposition: form-data; name="file"; filename="test.pdf"',
      'Content-Type: application/pdf',
      '',
      '%PDF-1.4 fake',
      `--${boundary}--`,
    ].join('\r\n')

    const res = await app.inject({
      method: 'POST',
      url: '/api/pdf',
      headers: { 'content-type': `multipart/form-data; boundary=${boundary}` },
      payload: body,
    })

    expect(res.statusCode).toBe(200)
    const parsed = JSON.parse(res.body)
    expect(parsed.score).toBe(8)
    expect(parsed.key_points).toHaveLength(2)
  })
})

import type { FastifyInstance } from 'fastify'
import pdfParse from 'pdf-parse'
import { claudeClient } from '../services/claudeClient'

interface PDFAnalysisResult {
  score: number
  explanation: string
  key_points: string[]
}

export async function pdfRoute(app: FastifyInstance) {
  app.post('/api/pdf', async (request, reply) => {
    const parts = request.parts()

    let persona = ''
    let fileBuffer: Buffer | null = null

    for await (const part of parts) {
      if (part.type === 'field' && part.fieldname === 'persona') {
        persona = part.value as string
      } else if (part.type === 'file' && part.fieldname === 'file') {
        const chunks: Buffer[] = []
        for await (const chunk of part.file) {
          chunks.push(chunk)
        }
        fileBuffer = Buffer.concat(chunks)
      }
    }

    if (!fileBuffer) {
      return reply.status(400).send({ error: 'No file uploaded' })
    }

    if (!persona) {
      return reply.status(400).send({ error: 'persona field required' })
    }

    const { text } = await pdfParse(fileBuffer)
    const truncatedText = text.slice(0, 4000)

    const response = await claudeClient.messages.create({
      model: 'claude-sonnet-4-6',
      max_tokens: 512,
      messages: [
        {
          role: 'user',
          content: `You are reviewing a document for relevance to a specific person.

Person: ${persona}

Document text:
${truncatedText}

Rate how relevant this document is to this person's situation on a scale of 1–10.

Return ONLY a JSON object (no markdown):
{
  "score": 7,
  "explanation": "One paragraph explaining relevance.",
  "key_points": ["point 1", "point 2", "point 3"]
}`,
        },
      ],
    })

    const textBlock = response.content.find((b) => b.type === 'text')
    let result: PDFAnalysisResult
    try {
      const raw = (textBlock?.type === 'text' ? textBlock.text : '{}')
        .replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim()
      result = JSON.parse(raw)
    } catch {
      result = { score: 0, explanation: 'Could not parse document', key_points: [] }
    }

    return result
  })
}
